#include <stdio.h>
int main(void) {
    int q[8], front = 0, rear = 0;
    for (int i = 1; i <= 3; i++) q[rear++] = i * 10;
    printf("%d\n", q[front++]);
    printf("%d\n", q[front]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int size = 5, rear = 3;
    for (int k = 0; k < 4; k++) rear = (rear + 1) % size;
    printf("%d\n", rear);
    return 0;
}

#include <stdio.h>
int main(void) {
    int d[8], f = 3, r = 3;
    d[r++] = 10;
    d[--f] = 20;
    d[r++] = 30;
    printf("%d %d %d\n", d[f], d[f+1], d[f+2]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[] = {1, 4, 2, 7, 3};
    int n = 5, w = 2;
    for (int i = 0; i + w <= n; i++) {
        int s = a[i] + a[i + 1];
        printf("%d ", s);
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int q[4], f = 0, r = 0, count = 0;
    for (int i = 1; i <= 3; i++) { q[r] = i; r = (r + 1) % 4; count++; }
    printf("%d\n", q[f]); f = (f + 1) % 4; count--;
    q[r] = 9; r = (r + 1) % 4; count++;
    printf("%d %d\n", q[f], count);
    return 0;
}

#include <stdio.h>
int s1[8], t1 = -1, s2[8], t2 = -1;
void move(void) { while (t1 >= 0) s2[++t2] = s1[t1--]; }
int main(void) {
    for (int i = 1; i <= 3; i++) s1[++t1] = i;
    move(); printf("%d\n", s2[t2--]);
    s1[++t1] = 4; move(); printf("%d\n", s2[t2--]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[] = {1, 3, 2, 5};
    int dq[4], f = 0, r = 0;
    for (int i = 0; i < 4; i++) {
        while (r > f && a[dq[r-1]] <= a[i]) r--;
        dq[r++] = i;
    }
    printf("%d\n", a[dq[f]]);
    return 0;
}
